insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,sumber_pdf,halaman,kalimat,kalimat_ruby,kosakata) values
('宿泊分野','衛生管理に含まれないものはどれですか？','["宿泊者の年収", "定期的な清掃", "消毒", "害虫駆除"]'::jsonb,0,'衛生管理は清掃・消毒・害虫駆除などです。',301,'00 · 旅館業法 (undang-undang usaha penginapan)','2号',6,'３. 衛生管理 宿泊施設は衛生的な環境を維持するために、定期的な清掃や消毒、害虫駆除などの衛 生管理を行う必要があります。また、宿泊者が安全に利用できるように、防火対策や 避難経路の確保も求められます。',null,'[]'::jsonb),
('宿泊分野','宿泊者が安全に利用できるように求められることはどれですか？','["防火対策と避難経路の確保", "客室の値上げ", "レストランの拡大", "駐車場の増設"]'::jsonb,0,'防火対策と避難経路の確保が求められます。',302,'00 · 旅館業法 (undang-undang usaha penginapan)','2号',6,'また、宿泊者が安全に利用できるように、防火対策や 避難経路の確保も求められます。 ５. 安全対策 火災や災害などの緊急時に備えて、消火設備や避難経路を整備することが求められます。 また、宿泊者が安全に避難できるよう、避難訓練を実施することも奨励されています。',null,'[]'::jsonb),
('宿泊分野','火災や災害の緊急時に備えて整備するものはどれですか？','["消火設備や避難経路", "売店", "プール", "会議室"]'::jsonb,0,'消火設備や避難経路の整備が求められます。',303,'00 · 旅館業法 (undang-undang usaha penginapan)','2号',6,'５. 安全対策 火災や災害などの緊急時に備えて、消火設備や避難経路を整備することが求められます。 また、宿泊者が安全に避難できるよう、避難訓練を実施することも奨励されています。 ６. 宿泊者名簿の作成と保管 宿泊施設は、宿泊者の氏名、住所、職業、宿泊日数などを記録した宿泊者名簿を作成し、 一定期間保管する義',null,'[]'::jsonb),
('宿泊分野','予約の問い合わせへの対応で最初に確認することはどれですか？','["希望日の空室", "お客様の職業", "支払い方法", "食事の好み"]'::jsonb,0,'希望日に部屋が空いているかを確認します。',304,'01 · フロント業務 (resepsionis)','2号',10,'お客様からの電話、メール、ウェブサイトなどを通じた予約の問い合わせについて、お客 様の宿泊希望日に部屋が空いているかどうかを確認する必要があります。もし部屋が空い ていない場合お客様が予約すること はできません。',null,'[]'::jsonb),
('宿泊分野','空室がない場合の対応として正しいのはどれですか？','["予約を受けることができない", "仮予約にする", "部屋を共有させる", "料金を下げて受ける"]'::jsonb,0,'空室がなければ予約は受けられません。',305,'01 · フロント業務 (resepsionis)','2号',10,'もし部屋が空い ていない場合お客様が予約すること はできません。お部屋が空いていな い状態のことを「満室」、お部屋が 空いている状態を「空室」と言いま す。 空室 あ き し つ 満室 ま ん し つ フロントで行う主な業務 予約管理 1. チェックイン業務 2. 館内でのお客様対応と 情報提供',null,'[]'::jsonb),
('宿泊分野','同じ部屋に複数の予約が入ってしまうことを何といいますか？','["ダブルブッキング", "ウォークイン", "アップセル", "ノーショー"]'::jsonb,0,'同じ部屋への重複予約をダブルブッキングといいます。',306,'01 · フロント業務 (resepsionis)','2号',10,'また、予約システムや予約管理のエラーにより同じ部屋に複数の予約が入ってしまうこと などを「ダブルブッキング」と言います。なお、オーバーブッキングが解消しなかったり、 ダブルブッキングが発生してしまった際には、お客様に事前に連絡ができる場合は連絡し て謝罪し、そのうえで代わりの近隣の宿泊施設のお部屋を用意する必要があります。',null,'[]'::jsonb),
('宿泊分野','ダブルブッキングが起きたときの対応として正しいのはどれですか？','["謝罪し、近隣の代替施設を用意する", "そのままにする", "料金を2倍にする", "部屋を狭くする"]'::jsonb,0,'事前連絡と謝罪のうえ、近隣の宿泊施設を用意します。',307,'01 · フロント業務 (resepsionis)','2号',10,'ーバーブッキングが解消しなかったり、 ダブルブッキングが発生してしまった際には、お客様に事前に連絡ができる場合は連絡し て謝罪し、そのうえで代わりの近隣の宿泊施設のお部屋を用意する必要があります。',null,'[]'::jsonb),
('宿泊分野','予約内容の調整や問い合わせで必ず確認することはどれですか？','["宿泊日と予約者名", "SNSのアカウント", "血液型", "趣味"]'::jsonb,0,'宿泊日と予約者名で、どのお客様かを特定します。',308,'01 · フロント業務 (resepsionis)','2号',13,'予約内容 の調整、宿泊後の忘れ物の問い合わせなど、いずれの場合でも、宿泊日と予約者名を必ず 確認し、どのお客様からの問い合わせなのかなどをしっかりと特定をして対応するように します。',null,'[]'::jsonb),
('宿泊分野','フロントで良い印象を与えるために重要なことはどれですか？','["清潔感・正しい姿勢・丁寧な言葉づかい", "派手な服装", "早口", "無表情"]'::jsonb,0,'清潔感ある身だしなみ、姿勢、丁寧な言葉づかいが重要です。',309,'01 · フロント業務 (resepsionis)','2号',15,'そのため、 お客様に良いイメージを与えられるように、清潔感がある身だしなみ、正しい姿勢、丁寧 な言葉づかい、で対応することが重要です。 などがあります。 宿泊予約の有無 お客様の氏名 ご予約のプラン ご予約人数 フロントで行う主な業務 予約管理 1. チェックイン業務 2. 館内でのお客様対応と 情報提供 3.',null,'[]'::jsonb),
('宿泊分野','追加料金の同意を得て上級の部屋に変更する販売方法を何といいますか？','["アップセル", "ダウンセル", "ノーショー", "オーバーブッキング"]'::jsonb,0,'アップグレード販売をアップセルといいます。',310,'01 · フロント業務 (resepsionis)','2号',16,'お客様が予約しているお部屋からのアップグレードのリクエストがある場合には、追加料 金に関する情報を提供し、同意を得た後に変更販売します（「アップセル」と言います）。 予約していないお客様（「ウォークインゲスト」と言います）が宿泊を希望した場合は、 空室状況を確認して、空室があればチェックイン対応を行います。',null,'[]'::jsonb),
('宿泊分野','予約なしで直接来館したお客様を何といいますか？','["ウォークインゲスト", "リピーター", "FIT", "コンシェルジュ"]'::jsonb,0,'予約なしの来館客をウォークインゲストといいます。',311,'01 · フロント業務 (resepsionis)','2号',16,'予約していないお客様（「ウォークインゲスト」と言います）が宿泊を希望した場合は、 空室状況を確認して、空室があればチェックイン対応を行います。 障害があるお客様がチェックインする際には、宿泊施設のバリアフリー対応（身体的な制 約や障害を持つ人々が使いやすくするための環境整備）について',null,'[]'::jsonb),
('宿泊分野','チェックインで予約確認の次に行うことはどれですか？','["ルームキーのお渡しと館内説明", "会計", "清掃", "朝食の提供"]'::jsonb,0,'鍵を渡し、館内や設備を説明します。',312,'01 · フロント業務 (resepsionis)','2号',17,'その際に気を付けなければいけないことは、お 客様が館内で迷わないように、お部屋への行き方、館内の利用できる場所への行き方や利 用可能な時間、さらには、火災や自然災害時に利用する非常口と避難経路など',null,'[]'::jsonb),
('宿泊分野','チェックイン時に必ず説明することはどれですか？','["非常口と避難経路", "従業員のシフト", "仕入れ先", "建物の築年数"]'::jsonb,0,'火災・災害時に使う非常口と避難経路を説明します。',313,'01 · フロント業務 (resepsionis)','2号',17,'は、お 客様が館内で迷わないように、お部屋への行き方、館内の利用できる場所への行き方や利 用可能な時間、さらには、火災や自然災害時に利用する非常口と避難経路などを丁寧に説 明する必要があります。',null,'[]'::jsonb),
('宿泊分野','会計業務でお客様に見せるものはどれですか？','["請求明細書", "シフト表", "清掃表", "予約台帳"]'::jsonb,0,'館内利用・宿泊料金・サービス料・税を明細にして請求します。',314,'01 · フロント業務 (resepsionis)','2号',22,'などの確認 会計またはキャッシャーと呼ばれる業務で、主な内容として館内利用、宿泊料金、サービ ス料、税など、お客様にご請求する内容を記載した請求明細書を発行してお客様にお見せ し、料金を請求します。',null,'[]'::jsonb),
('宿泊分野','支払い後、お客様に渡すものはどれですか？','["領収書", "献立表", "鍵", "浴衣"]'::jsonb,0,'「不要」と言われない限り領収書を発行します。',315,'01 · フロント業務 (resepsionis)','2号',22,'料金をお支払いいただいた後に、お客様から「不要です」と言わ れない限りは、領収書を発行してお客様にお渡しします。お支払いの方法がいくつかあり、 請求金額の間違いなどがないよう気をつける必要があります。',null,'[]'::jsonb),
('宿泊分野','日本のお金に関する習慣として正しいのはどれですか？','["チップの習慣はない", "必ずチップを渡す", "チップが給料の大半", "チップは違法"]'::jsonb,0,'日本ではチップを受け取る習慣がありません。',316,'01 · フロント業務 (resepsionis)','2号',22,'なお、日本では習慣としてチップを受け取る文化はありませんが、サービス料を宿泊料金 に含んで請求する場合と別に請求する場合があるほか、自治体によっては宿泊料金に加え て宿泊税、入湯税などを徴収することが必要な場合があります。',null,'[]'::jsonb),
('宿泊分野','自治体によって宿泊料金に加えて徴収されることがあるものはどれですか？','["宿泊税・入湯税", "消費税のみ", "チップ", "サービス料のみ"]'::jsonb,0,'自治体によって宿泊税・入湯税を徴収する場合があります。',317,'01 · フロント業務 (resepsionis)','2号',22,'ップを受け取る文化はありませんが、サービス料を宿泊料金 に含んで請求する場合と別に請求する場合があるほか、自治体によっては宿泊料金に加え て宿泊税、入湯税などを徴収することが必要な場合があります。',null,'[]'::jsonb),
('宿泊分野','夕食と朝食が料金に含まれるプランはどれですか？','["1泊2食", "B&B", "素泊まり", "デイユース"]'::jsonb,0,'1泊2食は夕食と朝食が含まれます。',318,'02 · 企画・広報 (perencanaan & promosi)','2号',26,'ゅくはく れんぱく わりびきりょうきん とくてん え さ ばあい れんぱく 企画業務にあたって覚えておくべき用語をいくつかご紹介します。 ・１泊２食 宿泊料金の中に夕食と朝食が含まれている宿泊プランです。',null,'[]'::jsonb),
('宿泊分野','朝食のみが料金に含まれるプランはどれですか？','["B&B", "1泊2食", "オールインクルーシブ", "ウォークイン"]'::jsonb,0,'B&Bは朝食のみ含まれます。',319,'02 · 企画・広報 (perencanaan & promosi)','2号',26,'主に旅館で販売されています ・ベッド& ブレックファースト（B＆B） 宿泊料金の中に朝食のみ含まれている宿泊プランです。主にホテルで販売されています ・連泊 同じ宿泊施設で2 泊以上の連続した宿泊を指します。',null,'[]'::jsonb),
('宿泊分野','連泊する場合の特徴として正しいのはどれですか？','["割引や特典がある場合がある", "必ず高くなる", "予約できない", "朝食なしのみ"]'::jsonb,0,'連泊は割引料金や特典が得られる場合があります。',320,'02 · 企画・広報 (perencanaan & promosi)','2号',26,'主にホテルで販売されています ・連泊 同じ宿泊施設で2 泊以上の連続した宿泊を指します。連泊は割引料金や特典を得ることが できる場合があります ・ウォークイン 事前の予約なしに直接宿泊施設に訪れてサービスを利用することを指します。',null,'[]'::jsonb),
('宿泊分野','サービスの利用を保証するために支払う金額を何といいますか？','["預り金（デポジット）", "チップ", "手数料", "宿泊税"]'::jsonb,0,'預り金（デポジット）は利用保証のための支払いです。',321,'02 · 企画・広報 (perencanaan & promosi)','2号',26,'一般的に、 宿泊施設では事前の予約がおすすめされていますが、予期せず立ち寄った顧客が空いてい る客室を利用することも可能です ・預り金 サービスの利用を保証するために支払われる金額を指します。',null,'[]'::jsonb),
('宿泊分野','自社サイトでオンライン予約を受け付けるシステムを何といいますか？','["ブッキングエンジン", "カスターセット", "シルバー", "ブッフェ"]'::jsonb,0,'ブッキングエンジンは自社サイトの予約システムです。',322,'02 · 企画・広報 (perencanaan & promosi)','2号',26,'宿泊施設の規模やニーズに応じて、カスタマイズされた ソリューションが提供されることが多いです ・ブッキングエンジン ブッキングエンジン（Booking Engine）は、宿泊施設が自社のウェブサイト上でオンライ ン予約を受け付けるためのシステムです。',null,'[]'::jsonb),
('宿泊分野','旅行会社やOTAを使わず直接予約・契約することを何といいますか？','["ダイレクトブッキング", "ブッキングエンジン", "アップセル", "オーバーブッキング"]'::jsonb,0,'代行会社を使わない直接予約をダイレクトブッキングといいます。',323,'02 · 企画・広報 (perencanaan & promosi)','2号',26,'お客様がご自身で宿泊予約を簡単に行えるよう にし、施設側も予約管理を効率的に行えるようにするツールです ・ダイレクトブッキング 旅行会社、OTA などの代行会社を利用せずに直接交渉や予約、契約まで行うことです。',null,'[]'::jsonb),
('宿泊分野','自由な個人旅行者を指す言葉はどれですか？','["FIT", "OTA", "ADR", "OCC"]'::jsonb,0,'FIT = Free Independent Traveler（個人旅行者）。',324,'02 · 企画・広報 (perencanaan & promosi)','2号',27,'インバウンド観光は、日本経済において重要な役割を果たし、地域経済の活性化や文化交 流の促進など多くのメリットをもたらします ・FIT Free Independent Traveler の略語であり、自由な個人旅行者を指します。',null,'[]'::jsonb),
('宿泊分野','観光地の宿泊施設の稼働率について正しいのはどれですか？','["繁忙期は上がり閑散期は下がる", "一年中同じ", "冬だけ上がる", "平日だけ上がる"]'::jsonb,0,'オンシーズンは稼働率が上がり、オフシーズンは下がります。',325,'02 · 企画・広報 (perencanaan & promosi)','2号',27,'観光地にあ る宿泊施設は、オンシーズンである長期休暇やGW のような大型連休は稼働率が上がり、 オフシーズンには稼働率が下がる傾向にあります。計算方法は予約室数÷ 総室数×100 で算出します 例）100 部屋の宿泊施設で70 部屋が稼働している状況は稼働率70％となります げんち じゆう こうどう りょこう さ しゅくはくりょうきん',null,'[]'::jsonb),
('宿泊分野','料金設定について正しいのはどれですか？','["高すぎると予約が減り、安すぎると収益が上がらない", "高ければ高いほど良い", "安ければ安いほど良い", "料金は関係ない"]'::jsonb,0,'価格と稼働率・収益のバランスが重要です。',326,'02 · 企画・広報 (perencanaan & promosi)','2号',28,'計算方法は、客室稼働率（OCC） × 客室平均単価（ADR）で算出します。客室価格を高く設定しすぎると予約が減って稼 働率は下がり、価格を下げて稼働率を上げようとすると収益は上がりません。',null,'[]'::jsonb),
('宿泊分野','日本語の敬語について正しいのはどれですか？','["3種類あり使い分ける", "1種類しかない", "使わなくてよい", "お客様には使わない"]'::jsonb,0,'敬語は3種類あり、場面で使い分けます。',327,'03 · 接客 (layanan tamu)','2号',39,'ま た、日本語には敬語というものがあり、お客様を接客する際には、敬語を適切に使う必要 があります。敬語には3 種類あり、それらを使い分ける必要があります。 3.接客の際の話し方 接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 せっきゃく さい きゃくさま め み は',null,'[]'::jsonb),
('宿泊分野','お客様の荷物を運ぶときの正しい対応はどれですか？','["丁寧に扱い客室まで運ぶ", "フロントに置く", "自分で持って行ってもらう", "外に置く"]'::jsonb,0,'荷物は丁寧に扱い、客室までお運びします。',328,'03 · 接客 (layanan tamu)','2号',40,'⑤お客様からお預かりした手荷物を客室まで運ぶ際には、丁寧な取り扱いを心がけ客室内 までお持ちします。 ⑥地図を使ってお客様に道案内をする際には、手のひらを上に向け4 本の指をそろえてご 案内します。',null,'[]'::jsonb),
('宿泊分野','地図で道案内をするときの正しい手の使い方はどれですか？','["手のひらを上にし4本の指をそろえる", "指1本で差す", "手を握る", "背を向ける"]'::jsonb,0,'手のひらを上に向け、4本の指をそろえて案内します。',329,'03 · 接客 (layanan tamu)','2号',40,'⑥地図を使ってお客様に道案内をする際には、手のひらを上に向け4 本の指をそろえてご 案内します。 ⑦ルームキーをお客様に渡す時には､相手から見て正面の方向に向けて両手でお渡ししま す。',null,'[]'::jsonb),
('宿泊分野','車いすのお客様への対応として正しいのはどれですか？','["広く入口に近い駐車スペースを案内する", "遠い場所を案内する", "階段を使ってもらう", "案内しない"]'::jsonb,0,'広くて近い駐車スペースをご案内します。',330,'03 · 接客 (layanan tamu)','2号',40,'また車いすのお客様がいらっしゃる時には、広くて宿泊施設に近い駐車スペー スをご案内します。 ⑪視覚障がいのあるお客様が来館された時には、何かお手伝いが出来ることがないか、お 客様の正面からお声かけをします。',null,'[]'::jsonb),
('宿泊分野（1号）','空室がない場合どうなりますか？','["予約を受けることができない", "自動で別室になる", "料金が下がる", "無料になる"]'::jsonb,0,'空室がなければ予約できません。',331,'1号 · 01 · フロント業務','1号',7,'もし部屋が空い ていない場合お客様が予約すること はできません。お部屋が空いていな い状態のことを「満室」、お部屋が 空いている状態を「空室」と言いま す。 空室 あ き し つ 満室 ま ん し つ フロントで行う主な業務 予約管理 1. チェックイン業務 2. 館内でのお客様対応と 情報提供',null,'[]'::jsonb),
('宿泊分野（1号）','予約の問い合わせで必ず確認することはどれですか？','["宿泊日と予約者名", "趣味", "血液型", "SNS"]'::jsonb,0,'宿泊日と予約者名でお客様を特定します。',332,'1号 · 01 · フロント業務','1号',9,'予約内容 の調整、宿泊後の忘れ物の問い合わせなど、いずれの場合でも、宿泊日と予約者名を必ず 確認し、どのお客様からの問い合わせなのかなどをしっかりと特定をして対応するように します。',null,'[]'::jsonb),
('宿泊分野（1号）','フロントで大切な対応はどれですか？','["清潔感・姿勢・丁寧な言葉づかい", "早口", "無表情", "私服"]'::jsonb,0,'身だしなみ・姿勢・言葉づかいが重要です。',333,'1号 · 01 · フロント業務','1号',11,'そのため、 お客様に良いイメージを与えられるように、清潔感がある身だしなみ、正しい姿勢、丁寧 な言葉づかい、で対応することが重要です。 などがあります。 また、日本人以外の外国人のお客様が日本の宿泊施設に泊まる場合は、パスポートのコピー をとって保管することが日本の法律で定められているので、忘れないようにお客様',null,'[]'::jsonb),
('宿泊分野（1号）','予約確認の次に行うことはどれですか？','["鍵を渡し館内を説明する", "会計する", "清掃する", "料理を運ぶ"]'::jsonb,0,'鍵を渡し、館内・設備を説明します。',334,'1号 · 01 · フロント業務','1号',12,'その際に気を付けなければいけないことは、お 客様が館内で迷わないように、お部屋への行き方、館内の利用できる場所への行き方や利 用可能な時間、さらには、火災や自然災害時に利用する非常口と避難経路など',null,'[]'::jsonb),
('宿泊分野（1号）','チェックイン時に説明する必要があるものはどれですか？','["非常口と避難経路", "従業員名", "仕入れ値", "シフト"]'::jsonb,0,'非常口と避難経路を丁寧に説明します。',335,'1号 · 01 · フロント業務','1号',12,'は、お 客様が館内で迷わないように、お部屋への行き方、館内の利用できる場所への行き方や利 用可能な時間、さらには、火災や自然災害時に利用する非常口と避難経路などを丁寧に説 明する必要があります。',null,'[]'::jsonb),
('宿泊分野（1号）','支払い後に渡すものはどれですか？','["領収書", "鍵", "浴衣", "朝食券"]'::jsonb,0,'料金受領後に領収書を渡します。',336,'1号 · 01 · フロント業務','1号',17,'料金をお支払いいただいた後に領収書を発行して、お客様にお渡 しします。お支払いの方法がいくつかあり、請求金額の間違いなどがないよう気をつける 必要があります。 なお、日本では習慣としてチップを受け取る文化はありませんが、サービス料を宿泊料金 に含んで請求する場合と別に請求する場合がありま',null,'[]'::jsonb),
('宿泊分野（1号）','日本の習慣として正しいのはどれですか？','["チップの習慣はない", "チップが必須", "チップは禁止", "チップは給料"]'::jsonb,0,'日本にチップの習慣はありません。',337,'1号 · 01 · フロント業務','1号',17,'なお、日本では習慣としてチップを受け取る文化はありませんが、サービス料を宿泊料金 に含んで請求する場合と別に請求する場合があります。 B . 会計 かんない りよう いんりょう かくにん きゃくさま しゅくはくいがい かんない りよう ふく いんりょう かんないりよう かんないりよう',null,'[]'::jsonb),
('宿泊分野（1号）','企画業務の内容として正しいのはどれですか？','["新しい宿泊プランやイベントを企画する", "会計をする", "清掃する", "電話を取る"]'::jsonb,0,'新プラン開発やイベント設計が企画業務です。',338,'1号 · 02 · 企画・広報','1号',20,'宿泊施設が提供するサービスを活用し、宿泊プラン、日帰りプラン、ランチビュッフェプ ランといったお客様に喜んでいただけるような新プランの開発やイベントを設計する仕事 です。その際には、ターゲットとする客層を正しく設定し、マーケティングによりその客 層のニーズをしっかりと理解し、適切なプランを企画立案していくことが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','夕食と朝食が含まれるプランはどれですか？','["1泊2食", "B&B", "素泊まり", "日帰り"]'::jsonb,0,'1泊2食は2食付きです。',339,'1号 · 02 · 企画・広報','1号',21,'・１泊２食 宿泊料金の中に夕食と朝食が含まれている宿泊プランです。主に旅館で販売されています ・ベッド& ブレックファースト（B＆B） 宿泊料金の中に朝食のみ含まれている宿泊プランです。',null,'[]'::jsonb),
('宿泊分野（1号）','朝食のみ含まれるプランはどれですか？','["B&B", "1泊2食", "オールインクルーシブ", "ウォークイン"]'::jsonb,0,'B&Bは朝食のみです。',340,'1号 · 02 · 企画・広報','1号',21,'主に旅館で販売されています ・ベッド& ブレックファースト（B＆B） 宿泊料金の中に朝食のみ含まれている宿泊プランです。主にホテルで販売されています ・連泊 同じ宿泊施設で2 泊以上の連続した宿泊を指します。',null,'[]'::jsonb),
('宿泊分野（1号）','連泊の特徴として正しいのはどれですか？','["割引や特典がある場合がある", "必ず高額", "予約不可", "朝食なし"]'::jsonb,0,'連泊は割引・特典が付く場合があります。',341,'1号 · 02 · 企画・広報','1号',21,'主にホテルで販売されています ・連泊 同じ宿泊施設で2 泊以上の連続した宿泊を指します。連泊は割引料金や特典を得ることが できる場合があります ・ウォークイン 事前の予約なしに直接宿泊施設に訪れてサービスを利用することを指します。',null,'[]'::jsonb),
('宿泊分野（1号）','予約なしで直接来館することを何といいますか？','["ウォークイン", "アップセル", "ノーショー", "FIT"]'::jsonb,0,'予約なしの来館をウォークインといいます。',342,'1号 · 02 · 企画・広報','1号',21,'連泊は割引料金や特典を得ることが できる場合があります ・ウォークイン 事前の予約なしに直接宿泊施設に訪れてサービスを利用することを指します。一般的に、 宿泊施設では事前の予約がおすすめされていますが、予期せず立ち寄った顧客が空いてい る客室を利用することも可能です ・預り金 サービスの利用を保証するために支払われる',null,'[]'::jsonb),
('宿泊分野（1号）','利用を保証するために支払う金額はどれですか？','["預り金（デポジット）", "チップ", "宿泊税", "手数料"]'::jsonb,0,'預り金＝デポジットです。',343,'1号 · 02 · 企画・広報','1号',21,'一般的に、 宿泊施設では事前の予約がおすすめされていますが、予期せず立ち寄った顧客が空いてい る客室を利用することも可能です ・預り金 サービスの利用を保証するために支払われる金額を指します。',null,'[]'::jsonb),
('宿泊分野（1号）','旅行会社を使わず直接予約することを何といいますか？','["ダイレクトブッキング", "ブッキングエンジン", "アップセル", "オーバーブッキング"]'::jsonb,0,'直接予約＝ダイレクトブッキングです。',344,'1号 · 02 · 企画・広報','1号',21,'デポジットと表記されるこ ともあります ・ダイレクトブッキング 旅行会社、OTA などの代行会社を利用せずに直接交渉や予約、契約まで行うことです。 施設側のメリットとしては手数料負担を減らすことができます ・OTA Online Travel Agent の略語です。',null,'[]'::jsonb),
('宿泊分野（1号）','予約状況に応じて価格を変える戦略はどれですか？','["ダイナミックプライシング", "アップセル", "ノーショー", "オールインクルーシブ"]'::jsonb,0,'需要に応じた価格戦略＝ダイナミックプライシングです。',345,'1号 · 02 · 企画・広報','1号',21,'代理 店やツアーオペレーターが提供するツアーパッケージを利用せず、自分旅行のプランを作 り、現地で自由に行動する旅行スタイルを指します。 ・ダイナミックプライシング お客様の予約状況や宿泊施設側の空室状況に応じて、宿泊施設の部屋の価格を高くしたり 安くしたり、宿泊施設の収益、利益を最も大きくするための価格戦略です。',null,'[]'::jsonb),
('宿泊分野（1号）','料金に全てのサービスが含まれるプランはどれですか？','["オールインクルーシブ", "B&B", "素泊まり", "1泊2食"]'::jsonb,0,'オールインクルーシブは全費用込みです。',346,'1号 · 02 · 企画・広報','1号',21,'況や宿泊施設側の空室状況に応じて、宿泊施設の部屋の価格を高くしたり 安くしたり、宿泊施設の収益、利益を最も大きくするための価格戦略です。 ・オールインクルーシブ 宿泊料金の中に全てのサービス費用が含まれているプランであり、飲料、軽食、アクティ ビティが含まれていることが多くなっています。',null,'[]'::jsonb),
('宿泊分野（1号）','観光地の稼働率について正しいのはどれですか？','["繁忙期に上がり閑散期に下がる", "常に一定", "冬に上がる", "平日に上がる"]'::jsonb,0,'繁忙期は上がり、閑散期は下がります。',347,'1号 · 02 · 企画・広報','1号',22,'観光地にある宿泊施設は、オンシーズンである長期休暇やGW のような大型連休 は稼働率が上がり、オフシーズンには稼働率が下がる傾向にあります。計算方法は予約室 数÷ 総室数×100 で算出します 例）100 部屋の宿泊施設で70 部屋が稼働している状況は稼働率70％となります ・ADR の説明 Average Daily Rate の略語',null,'[]'::jsonb),
('宿泊分野（1号）','稼働率（OCC）の計算方法はどれですか？','["予約室数÷総室数×100", "売上÷客室数", "客室数÷従業員数", "予約数÷宿泊日数"]'::jsonb,0,'OCC = 予約室数 ÷ 総室数 × 100 です。',348,'1号 · 02 · 企画・広報','1号',22,'る宿泊施設は、オンシーズンである長期休暇やGW のような大型連休 は稼働率が上がり、オフシーズンには稼働率が下がる傾向にあります。計算方法は予約室 数÷ 総室数×100 で算出します 例）100 部屋の宿泊施設で70 部屋が稼働している状況は稼働率70％となります ・ADR の説明 Average Daily Rate の略語で、客室一室あたりの平均販売単価のことです。',null,'[]'::jsonb),
('宿泊分野（1号）','料金設定について正しいのはどれですか？','["高すぎると予約が減り、安すぎると収益が上がらない", "高いほど良い", "安いほど良い", "関係ない"]'::jsonb,0,'価格と稼働率のバランスが重要です。',349,'1号 · 02 · 企画・広報','1号',22,'計算方法は、客室稼働率（OCC） × 客室平均単価（ADR）で算出します。客室価格を高く設定しすぎると予約が減って稼 働率は下がり、価格を下げて稼働率を上げようとすると収益は上がりません。',null,'[]'::jsonb),
('宿泊分野（1号）','自社ホームページで重要なことはどれですか？','["常に最新の情報に更新する", "更新しない", "料金を隠す", "写真を載せない"]'::jsonb,0,'最新情報の更新が重要です。',350,'1号 · 02 · 企画・広報','1号',24,'常に最新の情報をお客様にお届 けできるように更新をし、また、宿泊料金や施設案内などお客様が予約の際に知りたい情 報を掲載することも重要です。 ・ウェブサイトのデザインと使いやすさ お客様が簡単に情報を見つけられるように、わかりやすいナビゲーションやレイアウトを',null,'[]'::jsonb),
('宿泊分野（1号）','SNS運用で効果的な取り組みはどれですか？','["地元の観光協会や企業と連携する", "個人情報を載せる", "毎日同じ内容", "コメントを無視する"]'::jsonb,0,'地域との連携で観光全体を盛り上げます。',351,'1号 · 02 · 企画・広報','1号',25,'また、お客様の投稿にも積極的にコメントや「いいね」をすることで、 お客様とのコミュニケーションを活性化することが重要です。 ・地域との連携 地元の観光協会や地元企業とタッグを組んで、お互いにSNS アカウントをタグ付けしたり、 共同キャンペーンを行ったりすることで、地域全体の観光を盛り上げていくことが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','接客の基本とされるものはどれですか？','["あいさつ", "会計", "清掃", "予約"]'::jsonb,0,'あいさつは接客の基本です。',352,'1号 · 03 · 接客','1号',28,'接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 あいさつは接客の基本です。お客様にあいさつをすると、お客様は気持ちよく滞在す ることができます。',null,'[]'::jsonb),
('宿泊分野（1号）','敬語について正しいのはどれですか？','["3種類を使い分ける", "1種類のみ", "使わない", "お客様には砕けた話し方"]'::jsonb,0,'敬語は3種類あり、使い分けます。',353,'1号 · 03 · 接客','1号',32,'ま た、日本語には敬語というものがあり、お客様を接客する際には、敬語を適切に使う必要 があります。敬語には3 種類あり、それらを使い分ける必要があります。 3.接客の際の話し方 接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 せっきゃく さい きゃくさま め み は',null,'[]'::jsonb),
('宿泊分野（1号）','荷物を運ぶときの正しい対応はどれですか？','["丁寧に客室まで運ぶ", "フロントに置く", "外に置く", "客に運ばせる"]'::jsonb,0,'丁寧に扱い客室までお運びします。',354,'1号 · 03 · 接客','1号',33,'⑤お客様からお預かりした手荷物を客室まで運ぶ際には、丁寧な取り扱いを心がけ客室内 までお持ちします。 ⑥地図を使ってお客様に道案内をする際には、手のひらを上に向け4 本の指をそろえてご 案内します。',null,'[]'::jsonb),
('宿泊分野（1号）','地図で道案内するときの手の形はどれですか？','["手のひらを上にし4本の指をそろえる", "指1本で差す", "握りこぶし", "手を振る"]'::jsonb,0,'手のひらを上に、4本の指をそろえて案内します。',355,'1号 · 03 · 接客','1号',33,'⑥地図を使ってお客様に道案内をする際には、手のひらを上に向け4 本の指をそろえてご 案内します。 ⑦ルームキーをお客様に渡す時には､相手から見て正面の方向に向けて両手でお渡ししま す。',null,'[]'::jsonb),
('宿泊分野（1号）','宿泊施設で働くとき、かかってくる電話について正しいのはどれですか？','["予約など様々な電話がある", "予約の電話だけ", "社内の電話だけ", "電話はない"]'::jsonb,0,'予約を含め様々な電話があります。',356,'1号 · 03 · 接客','1号',34,'電話対応のポイントは、 ・電話を取る前にメモと筆記用具を用意しておく ・電話に出たら、まず名乗る ・電話を取り次ぐ場合は、相手の名前（会社名）を確認する ・特にお客様からの電話は、相手が受',null,'[]'::jsonb),
('宿泊分野（1号）','クレーム対応で最初にすべきことはどれですか？','["不快にさせたことをお詫びする", "原因を隠す", "自分だけで解決する", "無視する"]'::jsonb,0,'まずお詫び、次に原因確認、責任者へ報告です。',357,'1号 · 03 · 接客','1号',34,'クレーム対応のポイントは、 ・まず、不快にさせたことをお詫びする ・クレームの原因を丁寧に確認する ・責任者に報告する ことです。 また、自分のミスが原因であることが明らかな場合でも、自分ですべて解決しようとす ると、お客様の不満が溜まり更なるクレームにつながるため、責任者へ報告することが重 要',null,'[]'::jsonb),
('宿泊分野（1号）','自分のミスでも自分だけで解決しない理由はどれですか？','["不満が溜まり更なるクレームにつながる", "時間がかかる", "規則がない", "給料が下がる"]'::jsonb,0,'自分で抱えると不満が増え、大きなクレームになります。',358,'1号 · 03 · 接客','1号',34,'。 また、自分のミスが原因であることが明らかな場合でも、自分ですべて解決しようとす ると、お客様の不満が溜まり更なるクレームにつながるため、責任者へ報告することが重 要です。 6.クレーム（苦情）対応 接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 しゅくはくしせつ はたら よやく ふく さまざま でんわ',null,'[]'::jsonb),
('宿泊分野（1号）','洋食のカトラリー配置として正しいのはどれですか？','["左にフォーク、右にナイフとスプーン", "右にフォーク、左にナイフ", "すべて右", "すべて上"]'::jsonb,0,'フォークは左、ナイフ・スプーンは右です。',359,'1号 · 04 · レストランサービス','1号',41,'カトラリー類はプレートを中心に、左側にフォーク、 右側にナイフやスプーン、上部にデザートフォーク やデザートスプーン、左上部にパン皿を置きます。 食べる人は、ナイフは右手、フォークは左手に持つ のが基本です。',null,'[]'::jsonb),
('宿泊分野（1号）','洋食の食べ方の基本はどれですか？','["ナイフは右手、フォークは左手", "ナイフは左手、フォークは右手", "両手で持たない", "スプーンだけ使う"]'::jsonb,0,'ナイフ右手・フォーク左手が基本です。',360,'1号 · 04 · レストランサービス','1号',41,'ートを中心に、左側にフォーク、 右側にナイフやスプーン、上部にデザートフォーク やデザートスプーン、左上部にパン皿を置きます。 食べる人は、ナイフは右手、フォークは左手に持つ のが基本です。',null,'[]'::jsonb),
('宿泊分野（1号）','食事が終わったときの置き方はどれですか？','["ナイフとフォークを揃えて右下", "プレートの上に散らす", "膝の上に置く", "テーブルに置かない"]'::jsonb,0,'揃えて右下に置くのが一般的です。',361,'1号 · 04 · レストランサービス','1号',41,'コース料理の場合は、 ①オードブル ③魚料理 ②スープ ④肉料理 ⑥コーヒー ⑤デザート にㇵの字になるように置きます。食事終了後はナイフとフォークを揃えて右下に置くのが 一般的です。',null,'[]'::jsonb),
('宿泊分野（1号）','食物アレルギー対応で必ず行うことはどれですか？','["予約時・来店時にアレルギーの有無を確認する", "自己責任にする", "加熱すればよい", "何もしない"]'::jsonb,0,'必ず確認し、正確な情報を調理場・スタッフ間で共有します。',362,'1号 · 04 · レストランサービス','1号',42,'誤ってアレルギー反応が出る食材を食べないことが重要であり、予約時や来店時に、必ず アレルギーの有無をお客様に確認して、アレルギーがある場合は正確な情報を調理場やス タッフ内で共有します。',null,'[]'::jsonb),
('宿泊分野（1号）','レストランの安全衛生管理で求められることはどれですか？','["こまめな清掃で清潔を保つ", "週1回だけ掃除", "皿を洗わない", "消毒は不要"]'::jsonb,0,'こまめな清掃で常に清潔に保ちます。',363,'1号 · 04 · レストランサービス','1号',43,'適切な清掃作業は、レストランの安全衛生管理のうえでとても大切です。こまめな 清掃を継続して、常に清潔な状態を維持することが求められます。これらはお客様 が快適にお食事をしていただくことや、食中毒の防止にも繋がります。',null,'[]'::jsonb);
